#!/usr/bin/env bash
set -euo pipefail

# Open a pull request with the translation commit when it cannot be pushed to its branch.
#
# The current commit is pushed to a new branch prefixed by the Jira key, then a pull request
# targeting the original branch is opened. Exits with a non-zero code when it cannot be done.
#
# Usage: create-translations-pr.sh <jira_key>
#
# Expected environment variables:
#   GH_TOKEN           - token allowed to push a branch and open a pull request (may be empty, e.g. fork pull request)
#   BRANCH_NAME        - branch the commit could not be pushed to
#   GITHUB_REPOSITORY  - owner/name of the repository
#   GITHUB_API_URL     - GitHub API URL
#   JIRA_BASE_URL      - Jira URL, used to link the ticket (optional)

JIRA_KEY="${1:?Jira key is required}"
BRANCH_NAME="${BRANCH_NAME:-}"
GH_TOKEN="${GH_TOKEN:-}"
JIRA_BASE_URL="${JIRA_BASE_URL:-}"

warn() {
  echo "::warning::$*" >&2
}

main() {
  local head_branch payload response pr_url

  if [[ -z "$GH_TOKEN" || -z "$BRANCH_NAME" ]]; then
    warn "GH_TOKEN or BRANCH_NAME is not set. No pull request will be opened for the translation commit."
    return 1
  fi

  head_branch="${JIRA_KEY}-update-translations-${BRANCH_NAME//\//-}"

  if ! git push origin "HEAD:refs/heads/${head_branch}"; then
    warn "Failed to push the translation commit to branch ${head_branch}."
    return 1
  fi

  payload="$(
    JIRA_KEY="$JIRA_KEY" JIRA_BASE_URL="$JIRA_BASE_URL" HEAD_BRANCH="$head_branch" BASE_BRANCH="$BRANCH_NAME" php -r '
      $key = getenv("JIRA_KEY");
      $ticket = getenv("JIRA_BASE_URL") ? "[" . $key . "](" . rtrim(getenv("JIRA_BASE_URL"), "/") . "/browse/" . $key . ")" : $key;
      echo json_encode([
        "title" => "chore(lang): update translations",
        "head" => getenv("HEAD_BRANCH"),
        "base" => getenv("BASE_BRANCH"),
        "body" => "## Description\n\nTranslation files regenerated by the CI. They could not be pushed directly to `"
          . getenv("BASE_BRANCH") . "`.\n\n## Links\n\nFixes: " . $ticket . "\n",
      ]);
    '
  )"

  # the token is given through a config file to keep it out of the process list
  if ! response="$(curl --silent --show-error --fail --max-time 30 \
    --config <(printf 'header = "Authorization: Bearer %s"\n' "$GH_TOKEN") \
    --header "Accept: application/vnd.github+json" \
    --request POST --url "${GITHUB_API_URL}/repos/${GITHUB_REPOSITORY}/pulls" \
    --data "$payload")"; then
    warn "Branch ${head_branch} has been pushed but the pull request could not be opened."
    return 1
  fi

  pr_url="$(RESPONSE="$response" php -r 'echo json_decode((string) getenv("RESPONSE"), true)["html_url"] ?? "";')"
  echo "::notice::Translations could not be pushed to ${BRANCH_NAME}. Pull request opened: ${pr_url}"
}

main
